using System;
using System.IO;
namespace Ritm {
 public static class FocusTimerTest {
  static void Check(bool value,string label){if(!value)throw new Exception("Focus test: "+label);}
  public static void Run(string root){DateTime now=new DateTime(2026,10,28,12,0,0,DateTimeKind.Utc);var timer=new FocusTimer(null,()=>now);Check(timer.Remaining==1500&&!timer.State.Running,"initial duration");timer.Start();now=now.AddSeconds(91);timer.Pause();Check(timer.Remaining==1409,"pause uses elapsed wall time");now=now.AddMinutes(2);Check(timer.Remaining==1409,"pause remains stable");var saved=Json.Read<FocusState>(Json.Write(timer.State));timer=new FocusTimer(saved,()=>now);Check(timer.Remaining==1409,"paused timer restart");timer.Start();now=now.AddSeconds(1409);Check(timer.Tick()&&timer.State.Sessions==1&&timer.State.Mode=="break"&&!timer.State.Running&&timer.Remaining==300,"focus completion changes to paused break");Check(!timer.Tick()&&timer.State.Sessions==1,"completion is counted once");timer.Start();now=now.AddSeconds(301);Check(timer.Tick()&&timer.State.Mode=="focus"&&timer.State.Sessions==1&&timer.Remaining==1500,"break completion returns to focus");timer.Start();var running=Json.Read<FocusState>(Json.Write(timer.State));now=now.AddSeconds(100);var restored=new FocusTimer(running,()=>now);Check(restored.Remaining==1400&&restored.State.Running,"running restart keeps deadline");restored.Reset();Check(restored.Remaining==1500&&!restored.State.Running,"reset");var store=new Store(Path.Combine(root,"appearance"));store.SetPalette("ocean");store.Settings.Focus=restored.State;store.SaveLocalPreferences();var reopened=new Store(Path.Combine(root,"appearance"));Check(reopened.Settings.Palette=="ocean"&&reopened.Settings.Focus.Sessions==1,"preferences persist palette and focus");}
 }
}
